from itertools import combinations_with_replacement
import math
import os


class Example:
    def __init__(self, ident, values, label):
        self.ident = ident
        self.values = values
        self.label = label


class Settings:
    def __init__(self, entries):
        self.positive = int(entries["POSITIVE"][0])
        self.degree = int(entries["DEGREE"][0])
        self.threshold = float(entries["THRESHOLD"][0])
        self.lambdas = [float(value) for value in entries["LAMBDAS"]]
        self.gd_rate = float(entries["GD"][0])
        self.gd_iterations = int(entries["GD"][1])
        self.sgd_rate = float(entries["SGD"][0])
        self.batch_size = int(entries["SGD"][1])
        self.epochs = int(entries["SGD"][2])
        self.sgd_seed = int(entries["SGD"][3])
        self.softmax_rate = float(entries["SOFTMAX"][0])
        self.softmax_iterations = int(entries["SOFTMAX"][1])
        self.softmax_lambda = float(entries["SOFTMAX"][2])
        self.bootstrap_count = int(entries["BOOTSTRAP"][0])
        self.bootstrap_seed = int(entries["BOOTSTRAP"][1])
        self.permutation_count = int(entries["PERMUTATION"][0])
        self.permutation_seed = int(entries["PERMUTATION"][1])
        self.map_width = int(entries["MAP"][0])
        self.map_height = int(entries["MAP"][1])
        self.cost_fp = int(entries["COST"][0])
        self.cost_fn = int(entries["COST"][1])


class Statistics:
    def __init__(self, means, deviations):
        self.means = means
        self.deviations = deviations


def read_lines(path):
    with open(path) as file:
        return file.read().splitlines()


def read_examples(path):
    lines = read_lines(path)
    names = lines[0].split(",")[1:-1]
    examples = []
    for line in lines[1:]:
        fields = line.split(",")
        values = [float(field) for field in fields[1:-1]]
        examples.append(Example(fields[0], values, int(fields[-1])))
    return names, examples


def read_settings(path):
    entries = {}
    for line in read_lines(path):
        keyword, *values = line.split(" ")
        entries[keyword] = values
    return Settings(entries)


def read_inputs(directory):
    names, train = read_examples(os.path.join(directory, "train.csv"))
    _, test = read_examples(os.path.join(directory, "test.csv"))
    settings = read_settings(os.path.join(directory, "params.txt"))
    return names, train, test, settings


def expansion_tuples(base_count, degree):
    tuples = []
    for length in range(1, degree + 1):
        tuples.extend(combinations_with_replacement(range(base_count), length))
    return tuples


def expanded_names(names, tuples):
    return ["*".join(names[index] for index in indices) for indices in tuples]


def expanded_values(tuples, values):
    expanded = []
    for indices in tuples:
        product = values[indices[0]]
        for index in indices[1:]:
            product *= values[index]
        expanded.append(product)
    return expanded


def compute_statistics(rows, count):
    size = len(rows)
    means = []
    deviations = []
    for j in range(count):
        total = 0.0
        for row in rows:
            total += row[j]
        mean = total / size
        squares = 0.0
        for row in rows:
            squares += (row[j] - mean) * (row[j] - mean)
        means.append(mean)
        deviations.append(math.sqrt(squares / (size - 1)))
    return Statistics(means, deviations)


def standardize(values, statistics, count):
    vector = [1.0]
    for j in range(count):
        vector.append((values[j] - statistics.means[j]) / statistics.deviations[j])
    return vector

import math


def score(weights, vector):
    total = 0.0
    for weight, component in zip(weights, vector):
        total += weight * component
    return total


def probability(u):
    if u >= 0:
        return 1.0 / (1.0 + math.exp(-u))
    e = math.exp(u)
    return e / (1.0 + e)


def loss(u, target):
    return max(u, 0.0) - target * u + math.log(1.0 + math.exp(-abs(u)))


def average_loss(weights, vectors, targets):
    total = 0.0
    for vector, target in zip(vectors, targets):
        total += loss(score(weights, vector), target)
    return total / len(vectors)


def penalty(weights):
    total = 0.0
    for weight in weights[1:]:
        total += weight * weight
    return total


def objective(weights, vectors, targets, lam):
    return average_loss(weights, vectors, targets) + lam * penalty(weights) / 2


def gradient(weights, vectors, targets, lam):
    size = len(weights)
    totals = [0.0] * size
    for vector, target in zip(vectors, targets):
        error = probability(score(weights, vector)) - target
        for j in range(size):
            totals[j] += error * vector[j]
    count = len(vectors)
    result = [totals[0] / count]
    for j in range(1, size):
        result.append(totals[j] / count + lam * weights[j])
    return result


def hessian(weights, vectors, lam):
    size = len(weights)
    totals = [[0.0] * size for _ in range(size)]
    for vector in vectors:
        pi = probability(score(weights, vector))
        variance = pi * (1.0 - pi)
        for j in range(size):
            row = totals[j]
            for k in range(j + 1):
                row[k] += variance * vector[j] * vector[k]
    count = len(vectors)
    matrix = [[0.0] * size for _ in range(size)]
    for j in range(size):
        for k in range(j + 1):
            value = totals[j][k] / count
            if j == k and j >= 1:
                value += lam
            matrix[j][k] = value
            matrix[k][j] = value
    return matrix

from math import gcd


class Confusion:
    def __init__(self, predictions, targets):
        self.tp = 0
        self.fp = 0
        self.tn = 0
        self.fn = 0
        for prediction, target in zip(predictions, targets):
            if prediction == 1 and target == 1:
                self.tp += 1
            elif prediction == 1:
                self.fp += 1
            elif target == 0:
                self.tn += 1
            else:
                self.fn += 1


class RocPoint:
    def __init__(self, threshold, tp, fp):
        self.threshold = threshold
        self.tp = tp
        self.fp = fp


def fixed(value, places):
    text = f"{value:.{places}f}"
    if text.startswith("-") and float(text) == 0:
        return text[1:]
    return text


def ratio(numerator, denominator):
    if denominator == 0:
        return "-"
    rounded = (20000 * numerator + denominator) // (2 * denominator)
    return f"{rounded // 10000}.{rounded % 10000:04d}"


def fraction(numerator, denominator):
    divisor = gcd(numerator, denominator)
    reduced = f"{numerator // divisor}/{denominator // divisor}"
    return f"{reduced} {ratio(numerator, denominator)}"


def auc(scores, targets):
    order = sorted(range(len(scores)), key=lambda i: scores[i])
    positives = sum(targets)
    negatives = len(targets) - positives
    rank_sum = 0
    start = 0
    while start < len(order):
        end = start
        while end + 1 < len(order) and scores[order[end + 1]] == scores[order[start]]:
            end += 1
        for position in range(start, end + 1):
            if targets[order[position]] == 1:
                rank_sum += start + end + 2
        start = end + 1
    return rank_sum - positives * (positives + 1), 2 * positives * negatives


def roc_points(probabilities, targets):
    order = sorted(range(len(probabilities)), key=lambda j: -probabilities[j])
    points = []
    tp = 0
    fp = 0
    for position, j in enumerate(order):
        if targets[j] == 1:
            tp += 1
        else:
            fp += 1
        last = position + 1 == len(order)
        if last or probabilities[order[position + 1]] != probabilities[j]:
            points.append(RocPoint(probabilities[j], tp, fp))
    return points

import math

from logistic import gradient, hessian


MODULUS = 2147483647
MULTIPLIER = 48271
CHECKPOINT_INTERVAL = 100
NEWTON_ITERATIONS = 10


class Minstd:
    def __init__(self, seed):
        self.state = seed

    def draw(self):
        self.state = MULTIPLIER * self.state % MODULUS
        return self.state


def shuffle(sequence, generator):
    for i in range(len(sequence) - 1, 0, -1):
        k = generator.draw() % (i + 1)
        sequence[i], sequence[k] = sequence[k], sequence[i]


def move(weights, direction, rate):
    return [weight - rate * step for weight, step in zip(weights, direction)]


def gradient_descent(vectors, targets, lam, rate, iterations):
    weights = [0.0] * len(vectors[0])
    checkpoints = [(0, weights)]
    for t in range(1, iterations + 1):
        weights = move(weights, gradient(weights, vectors, targets, lam), rate)
        if t % CHECKPOINT_INTERVAL == 0:
            checkpoints.append((t, weights))
    return checkpoints


def stochastic_gradient_descent(vectors, targets, lam, rate, batch_size, epochs, seed):
    generator = Minstd(seed)
    order = list(range(len(vectors)))
    weights = [0.0] * len(vectors[0])
    checkpoints = [(0, weights)]
    for epoch in range(1, epochs + 1):
        shuffle(order, generator)
        for start in range(0, len(order), batch_size):
            batch = order[start:start + batch_size]
            direction = gradient(
                weights, [vectors[i] for i in batch], [targets[i] for i in batch], lam
            )
            weights = move(weights, direction, rate)
        checkpoints.append((epoch, weights))
    return checkpoints


def cholesky(matrix):
    size = len(matrix)
    lower = [[0.0] * size for _ in range(size)]
    for j in range(size):
        for i in range(j, size):
            total = 0.0
            for k in range(j):
                total += lower[i][k] * lower[j][k]
            remainder = matrix[i][j] - total
            if i == j:
                lower[j][j] = math.sqrt(remainder)
            else:
                lower[i][j] = remainder / lower[j][j]
    return lower


def solve(lower, values):
    size = len(lower)
    middle = [0.0] * size
    for i in range(size):
        total = 0.0
        for k in range(i):
            total += lower[i][k] * middle[k]
        middle[i] = (values[i] - total) / lower[i][i]
    solution = [0.0] * size
    for i in range(size - 1, -1, -1):
        total = 0.0
        for k in range(i + 1, size):
            total += lower[k][i] * solution[k]
        solution[i] = (middle[i] - total) / lower[i][i]
    return solution


def newton_direction(weights, vectors, targets, lam):
    direction = gradient(weights, vectors, targets, lam)
    step = solve(cholesky(hessian(weights, vectors, lam)), direction)
    return direction, step


def newton_method(vectors, targets, lam):
    weights = [0.0] * len(vectors[0])
    checkpoints = [(0, weights)]
    for t in range(1, NEWTON_ITERATIONS + 1):
        _, step = newton_direction(weights, vectors, targets, lam)
        weights = [weight - delta for weight, delta in zip(weights, step)]
        checkpoints.append((t, weights))
    return checkpoints

import math

from logistic import score


CHECKPOINT_INTERVAL = 100


def shifted_scores(weights, vector):
    scores = [score(row, vector) for row in weights]
    top = max(scores)
    return [value - top for value in scores]


def exponential_total(shifted):
    total = 0.0
    for value in shifted:
        total += math.exp(value)
    return total


def probabilities(weights, vector):
    shifted = shifted_scores(weights, vector)
    total = exponential_total(shifted)
    return [math.exp(value) / total for value in shifted]


def predicted_class(class_probabilities):
    return class_probabilities.index(max(class_probabilities))


def loss(weights, vector, label):
    shifted = shifted_scores(weights, vector)
    return math.log(exponential_total(shifted)) - shifted[label]


def average_loss(weights, vectors, labels):
    total = 0.0
    for vector, label in zip(vectors, labels):
        total += loss(weights, vector, label)
    return total / len(vectors)


def penalty(weights):
    total = 0.0
    for row in weights:
        for weight in row[1:]:
            total += weight * weight
    return total


def objective(weights, vectors, labels, lam):
    return average_loss(weights, vectors, labels) + lam * penalty(weights) / 2


def gradient(weights, vectors, labels, lam):
    classes = len(weights)
    size = len(weights[0])
    totals = [[0.0] * size for _ in range(classes)]
    for vector, label in zip(vectors, labels):
        class_probabilities = probabilities(weights, vector)
        for k in range(classes):
            error = class_probabilities[k] - (1.0 if label == k else 0.0)
            row = totals[k]
            for j in range(size):
                row[j] += error * vector[j]
    count = len(vectors)
    result = []
    for k in range(classes):
        row = [totals[k][0] / count]
        for j in range(1, size):
            row.append(totals[k][j] / count + lam * weights[k][j])
        result.append(row)
    return result


def train(vectors, labels, classes, lam, rate, iterations):
    weights = [[0.0] * len(vectors[0]) for _ in range(classes)]
    checkpoints = [(0, weights)]
    for t in range(1, iterations + 1):
        direction = gradient(weights, vectors, labels, lam)
        weights = [
            [weight - rate * step for weight, step in zip(row, steps)]
            for row, steps in zip(weights, direction)
        ]
        if t % CHECKPOINT_INTERVAL == 0:
            checkpoints.append((t, weights))
    return checkpoints
